Algorithm Bien
  Write "Fin del programa";
EndAlgorithm

Algorithm Falla
  Define divisor As Integer <- 0;
  Write "Antes del fallo";
  Write 10 Div divisor;
  Write "Esto nunca se escribe";
EndAlgorithm

Algorithm Espera
  Define edad As Integer <- 0;
  Write "¿Cuántos años tienes?";
  Read edad;
  Write "El año que viene tendrás ", edad + 1;
EndAlgorithm
